# Generated by manage.py generate_test_cases.
"""Policy and organizer identity checks on the event scheduling action."""

from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.calendar_fixtures import SchedulingFixtures


class TestScheduleComponent(SchedulingFixtures, BloomerpComponentTestCase):
    view_name = "components_calendar_schedule"

    def extendedSetup(self) -> None:
        """Create a local organizer event with explicitly invited recipients."""
        self.prepare_calendar()
        self.event = self.local_event()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Require login and independent event permissions before exposing send controls."""
        kwargs = {"event_id": self.event.pk}
        return [
            RequestScenario(
                name="Anonymous scheduling requires login",
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Inbox ownership does not authorize calendar scheduling",
                user=self.owner,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Organizer controls show permitted sender",
                user=self.actor,
                view_kwargs=kwargs,
                expected=ExpectedResult(
                    response_validators=self.contains_text(self.account.email_address)
                ),
            ),
            RequestScenario(
                name="Invalid action cannot send mail",
                user=self.actor,
                method="POST",
                view_kwargs=kwargs,
                data={"action": "PUBLISH", "email_account_id": str(self.account.pk)},
                expected=ExpectedResult(status_code=400),
            ),
        ]
